import{_ as t,o as d,c as a,a3 as o}from"./chunks/framework.cNy3aYYk.js";const m=JSON.parse('{"title":"Attendance — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Attendance — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/attendance"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Attendance — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/attendance"}]]},"headers":[],"relativePath":"developer-guide/attendance.md","filePath":"developer-guide/attendance.md","lastUpdated":1791043992000}'),n={name:"developer-guide/attendance.md"};function c(i,e,r,s,l,p){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="attendance-—-developer-guide" tabindex="-1">Attendance — Developer Guide <a class="header-anchor" href="#attendance-—-developer-guide" aria-label="Permalink to &quot;Attendance — Developer Guide&quot;">​</a></h1><p>Slug <code>attendance</code>, middleware <code>module:attendance</code>, permissions <code>attendance.*</code>. Hard-depends on <code>employees</code>. Catalog <strong>1.6.0</strong>.</p><h2 id="domain" tabindex="-1">Domain <a class="header-anchor" href="#domain" aria-label="Permalink to &quot;Domain&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Model</th><th>Table</th><th>Notes</th></tr></thead><tbody><tr><td><code>AttendanceRecord</code></td><td><code>attendance_records</code></td><td>Unique <code>(tenant_id, employee_id, date)</code>; soft deletes; work_mode + reason FKs; check-in/out IP + lat/lng</td></tr><tr><td><code>AttendanceRecordActivity</code></td><td><code>attendance_record_activities</code></td><td>Timeline: who / why / field diffs; newest-first</td></tr><tr><td><code>AttendanceReason</code></td><td><code>attendance_reasons</code></td><td>Catalog kinds <code>check_in_late</code> / <code>check_out</code>; protected <code>is_other</code></td></tr></tbody></table><p>Enums: <code>AttendanceStatusEnum</code>, <code>AttendanceWorkModeEnum</code>, <code>AttendanceReasonKindEnum</code>, <code>AttendanceActivityTypeEnum</code>.</p><p>Service: <code>AttendanceRecordService</code> (CRUD + stats + today + checkIn/checkOut + optional <code>markLoginCheckIn</code> + <code>timeline</code>). IP always from <code>request()-&gt;ip()</code>; coordinates best-effort from the client. Manual <code>store</code> / <code>update</code> require <code>change_reason</code> (min 5 chars) — uses existing <code>attendance.create</code> / <code>attendance.update</code> (no extra permission).</p><p><strong>Ownership:</strong> Staff may only act on their linked active employee. Self check-in/out (<code>POST .../check-in</code>, <code>.../check-out</code>, <code>GET .../today</code>) requires a linked active employee and <code>attendance_self_check_enabled</code> — not <code>attendance.create</code> / <code>attendance.update</code>. Owner/Admin are org-wide. Department managers (<code>departments.manager_id</code>) are scoped to employees in their managed departments (<code>department_employee</code> ∪ employees linked via <code>department_user</code>, plus own linked employee). Spatie <code>manager</code> without a department assignment is self-scoped. List/KPIs/CRUD use <code>AttendanceRecordPolicy::visibleEmployeeIds</code> / <code>canAccessEmployee</code>.</p><p>Tenant settings (<code>attendance</code> group): office hours, <code>attendance_self_check_enabled</code>, <code>attendance_auto_check_in_on_login</code> (default <strong>false</strong>), <code>attendance_require_late_reason</code>, <code>attendance_late_report_enabled</code> (default <strong>false</strong>) + <code>attendance_late_report_time</code> (default <code>09:30</code>), <code>attendance_daily_report_enabled</code> (default <strong>false</strong>) + <code>attendance_daily_report_time</code> (default <code>08:00</code>), <code>remote_office_start_time</code>, <code>remote_grace_minutes</code>, <code>work_week_days</code>, <code>employee_custom_schedules_enabled</code>, <code>payroll_deduct_late</code> + <code>payroll_late_deduction_rules</code>, <code>payroll_deduct_absent</code>, <code>payroll_deduct_unpaid_leave</code>. Workspace timezone drives “today”, late thresholds, and digest send clocks. Auto-login check-in is skipped when the user would be late and late reasons are required. When custom schedules are enabled, late thresholds prefer each employee’s on-site / remote start times. Late remote check-ins store status <strong>Late</strong> with work mode <strong>Remote</strong>.</p><h3 id="daily-email-digests" tabindex="-1">Daily email digests <a class="header-anchor" href="#daily-email-digests" aria-label="Permalink to &quot;Daily email digests&quot;">​</a></h3><p>Scheduled command <code>attendance:send-daily-reports</code> (every 5 minutes, <code>onOneServer</code>) walks entitled tenants:</p><table tabindex="0"><thead><tr><th>Digest</th><th>Setting toggle</th><th>Send time key</th><th>Contents</th><th>Recipients</th></tr></thead><tbody><tr><td>Late today</td><td><code>attendance_late_report_enabled</code></td><td><code>attendance_late_report_time</code></td><td>Today’s <code>status=late</code> check-ins + active employees past on-site start+grace with no check-in (excludes approved leave when Leave entitled; skips non-work days for the not-arrived bucket)</td><td>Owners / Admins (full company); department managers (managed employees only); requires <code>attendance.view</code></td></tr><tr><td>Yesterday</td><td><code>attendance_daily_report_enabled</code></td><td><code>attendance_daily_report_time</code></td><td>Yesterday counts + late rows + missing check-out (<code>check_in</code> set, <code>check_out</code> null)</td><td>Same</td></tr></tbody></table><p>Idempotency via <code>daily_summary_deliveries</code> kinds <code>attendance_late_daily</code> / <code>attendance_yesterday_daily</code>. Notifications: <code>AttendanceLateDigestNotification</code> / <code>AttendanceYesterdayDigestNotification</code> (database + mail). Empty late digest skips send; yesterday skips when there are no records for that date. Department managers receive a per-recipient scoped payload (skipped when their team has no attention items).</p><h2 id="backend-layout" tabindex="-1">Backend layout <a class="header-anchor" href="#backend-layout" aria-label="Permalink to &quot;Backend layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Path</th></tr></thead><tbody><tr><td>Models</td><td><code>AttendanceRecord</code>, <code>AttendanceRecordActivity</code>, <code>AttendanceReason</code></td></tr><tr><td>Services</td><td><code>AttendanceRecordService</code>, <code>AttendanceReasonService</code>, <code>AttendanceDailyReportService</code></td></tr><tr><td>Controllers</td><td><code>AttendanceRecordController</code>, <code>AttendanceReasonController</code></td></tr><tr><td>Commands</td><td><code>attendance:send-daily-reports</code></td></tr><tr><td>Tests</td><td><code>tests/Feature/Tenant/Attendance/</code></td></tr></tbody></table><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><p>See <a href="/api/tenant-v1-attendance">tenant-v1-attendance.md</a>.</p><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><ul><li><code>attendanceRecordService</code> / <code>attendanceReasonService</code> (+ <code>timeline</code>)</li><li>List: search + check-in/out + HH:MM timer + reasons dialog (best-effort geolocation)</li><li>Create/edit: required change reason + best-effort geolocation</li><li>View: IP/location details + edit history timeline</li><li>Login / 2FA / passkey: optional coordinates for auto check-in</li><li>Settings → Attendance: late / yesterday digest toggles + send times (workspace timezone)</li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --compact</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/Feature/Tenant/Attendance</span></span></code></pre></div>',20)])])}const u=t(n,[["render",c]]);export{m as __pageData,u as default};
